  "cards": [
    {
      "actionId": "child_play_indoors_when_poor",
      "title": "Keep children's play indoors",
      "why": "Children are more vulnerable to high pollution levels. Keeping them inside reduces their exposure by {{impact.child_play_indoors_when_poor.pct}}.",
      "when": "Today",
      "steps": [
        "Move play areas to an indoor room",
        "Limit outdoor activity strictly",
        "Choose quiet indoor games"
      ]
    },
    {
      "actionId": "wfh_on_worst_day",
      "title": "Work from home if possible",
      "why": "Avoiding the commute reduces your exposure and saves {{co2e.wfh_on_worst_day}} in emissions.",
      "when": "Today",
      "steps": [
        "Request remote work for the day",
        "Avoid all non-essential travel",
        "Use digital meetings"
      ]
    },
    {
      "actionId": "close_windows_at_peak",
      "title": "Seal your home during peak hours",
      "why": "Closing windows prevents outdoor pollutants from entering, reducing indoor PM2.5 by {{impact.close_windows_at_peak.pct}}.",
      "when": "Outside {{best.start}}-{{best.end}}",
      "steps": [
        "Keep windows and doors shut",
        "Use weather stripping for gaps",
        "Use air purifiers if available"
      ]
    },
    {
      "actionId": "damp_mop_dont_sweep",
      "title": "Damp mop instead of sweeping",
      "why": "Dry sweeping kicks up dust and increases indoor particle counts. Damp mopping keeps surfaces clean effectively.",
      "when": "During daily cleaning",
      "steps": [
        "Use a wet cloth or mop",
        "Avoid using dry brooms",
        "Clean surfaces frequently"
      ]
    },
    {
      "actionId": "cooking_ventilation",
      "title": "Improve cooking ventilation",
      "why": "Cooking can significantly increase indoor PM2.5. Proper ventilation reduces this impact by {{impact.cooking_ventilation.pct}}.",
      "when": "During meal preparation",
      "steps": [
        "Use exhaust fans while cooking",
        "Keep lids on pots",
        "Avoid open-flame cooking if possible"
      ]
    },
    {
      "actionId": "warmth_without_burning",
      "title": "Choose clean heating methods",
      "why": "Burning fuels for warmth adds to local pollution. Clean alternatives improve air quality by {{impact.warmth_without_burning.pct}}.",
      "when": "Ongoing",
      "steps": [
        "Use electric heaters",
        "Wear extra layers for warmth",
        "Avoid open fires or coal"
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Encourage community no-burning",
      "why": "Collective action helps lower local pollution levels by {{impact.community_no_burning.pct}}.",
      "when": "Ongoing",
      "steps": [
        "Talk to neighbors about air quality",
        "Report open burning incidents",
        "Share clean heating tips"
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "Children have developing lungs; keep them indoors and monitor for any signs of respiratory distress."
    },
    {
      "group": "adult",
      "note": "Adults should minimize outdoor exertion today to reduce the total volume of air inhaled."
    }
  ],
  "tradeoffs": [
    "Closing windows reduces fresh air circulation; use an air purifier or fan with a filter to maintain indoor air quality.",
    "Working from home reduces commute exposure but may increase indoor energy consumption."
  ]
}

